using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class PostTools
{
    [McpServerTool, Description("Get a list of posts, optionally filtered by user ID.")]
    public static async Task<string> GetPosts(
        IHttpClientFactory httpClientFactory,
        [Description("Filter posts by this user ID. Omit to get all posts.")] int? userId = null)
    {
        using var client = httpClientFactory.CreateClient("api");
        var url = userId.HasValue ? $"/posts?userId={userId}" : "/posts";
        var posts = await client.GetFromJsonAsync<List<Post>>(url);
        return System.Text.Json.JsonSerializer.Serialize(posts);
    }

    [McpServerTool, Description("Get a single post by its ID.")]
    public static async Task<string> GetPost(
        IHttpClientFactory httpClientFactory,
        [Description("The ID of the post to retrieve.")] int postId)
    {
        using var client = httpClientFactory.CreateClient("api");
        var post = await client.GetFromJsonAsync<Post>($"/posts/{postId}");
        return System.Text.Json.JsonSerializer.Serialize(post);
    }

    [McpServerTool, Description("Create a new post.")]
    public static async Task<string> CreatePost(
        IHttpClientFactory httpClientFactory,
        [Description("Title of the new post.")] string title,
        [Description("Body content of the new post.")] string body,
        [Description("User ID of the post author.")] int userId)
    {
        using var client = httpClientFactory.CreateClient("api");
        var payload = new { title, body, userId };
        var response = await client.PostAsJsonAsync("/posts", payload);
        response.EnsureSuccessStatusCode();
        var created = await response.Content.ReadAsStringAsync();
        return created;
    }
}

public record Post(
    [property: JsonPropertyName("userId")] int UserId,
    [property: JsonPropertyName("id")] int Id,
    [property: JsonPropertyName("title")] string Title,
    [property: JsonPropertyName("body")] string Body);

